// Microsoft SOC Brief 22 Oct 2026 - Storm-0940: ConnectWise multi-tenant apps and published IPs, service principal sign-ins and Graph calls since 1 October
// Columns as on the AADServicePrincipalSignInLogs and MicrosoftGraphActivityLogs references cited beside this query. Not run against a tenant in this pass.
let cwApps = dynamic(["506e08f9-6e9a-4da4-942b-a099a03644ae", "24205314-2b89-4e07-a2a4-579e898a5640", "0de14c77-b9b0-4137-9360-34878a929827"]);
let iocIPs = dynamic(["144.172.64.128", "144.172.64.99", "144.172.64.60", "187.15.88.186", "187.15.90.217", "187.15.89.186"]);
let since = datetime(2026-10-01);
let signins = AADServicePrincipalSignInLogs
| where TimeGenerated >= since
| where AppId in (cwApps) or IPAddress in (iocIPs)
| summarize SignIns = count(), Failures = countif(ResultType != "0"), SignInIPs = make_set(IPAddress, 50), Resources = make_set(ResourceDisplayName, 20), First = min(TimeGenerated), Last = max(TimeGenerated) by AppId, ServicePrincipalId, ServicePrincipalName;
let graph = MicrosoftGraphActivityLogs
| where TimeGenerated >= since
| where AppId in (cwApps) or IPAddress in (iocIPs)
| summarize GraphCalls = count(), Writes = countif(RequestMethod in ("POST", "PATCH", "PUT", "DELETE")), GraphIPs = make_set(IPAddress, 50), SampleUris = make_set(RequestUri, 25) by AppId, ServicePrincipalId;
signins
| join kind=fullouter graph on AppId, ServicePrincipalId
| project AppId = coalesce(AppId, AppId1), ServicePrincipalId = coalesce(ServicePrincipalId, ServicePrincipalId1), ServicePrincipalName, SignIns, Failures, First, Last, SignInIPs, Resources, GraphCalls, Writes, GraphIPs, SampleUris
| order by Writes desc, SignIns desc

// Microsoft SOC Brief 21 Oct 2026 - Sentinel/Log Analytics tables whose ingestion dropped (pairs with Unified Data Management preview)
// Columns as on the Usage table reference cited beside this query. Not run against a tenant in this pass.
let lookback = 14d;
let daily = Usage
| where TimeGenerated > ago(lookback + 1d)
| where StartTime >= startofday(ago(lookback)) and EndTime < startofday(now())
| summarize MB = sum(Quantity) by DataType, Day = bin(StartTime, 1d);
let lastDay = startofday(ago(1d));
daily
| summarize MedianMB = percentile(MB, 50), LastSeen = max(Day), LastDayMB = sumif(MB, Day == lastDay) by DataType
| where LastSeen < lastDay or LastDayMB < 0.3 * MedianMB
| extend Status = iff(LastSeen < lastDay, "stopped reporting", "dropped below 30% of median")
| project DataType, Status, MedianMB = round(MedianMB, 2), LastDayMB = round(LastDayMB, 2), LastSeen
| order by MedianMB desc

// Microsoft SOC Brief 20 Oct 2026 - devices still exposed to CVE-2026-70197 (.NET RCE, fix incomplete per MSRC 19 Oct)
// Defender XDR advanced hunting. Columns as on the DeviceTvmSoftwareVulnerabilities table reference cited beside this query.
// Not ingested into Sentinel. Not run against a tenant in this pass.
DeviceTvmSoftwareVulnerabilities
| where CveId == "CVE-2026-70197"
| summarize Devices = dcount(DeviceId), Versions = make_set(SoftwareVersion, 20), Names = make_set(DeviceName, 50)
    by SoftwareVendor, SoftwareName, OSPlatform, VulnerabilitySeverityLevel, RecommendedSecurityUpdate
| order by Devices desc

// Microsoft SOC Brief 11 Oct 2026 - Arc-enabled Kubernetes clusters with the retiring Key Vault Secrets Provider extension
// Azure Resource Graph. Table, resource type and properties.ExtensionType follow the Microsoft sample cited beside this query.
// The extension type string is the one Microsoft's migration guide filters on. Not run against a tenant in this pass.
KubernetesConfigurationResources
| where type =~ 'microsoft.kubernetesconfiguration/extensions'
| where tolower(tostring(properties.ExtensionType)) == 'microsoft.azurekeyvaultsecretsprovider'
| parse id with connectedClusterId '/providers/Microsoft.KubernetesConfiguration/Extensions' *
| project connectedClusterId, extensionName = name, subscriptionId, resourceGroup, location
| order by connectedClusterId asc

// Microsoft SOC Brief 8 Oct 2026 - malicious URLs in Teams messages, QR-code-borne ones first
// MessageUrlInfo and MessageEvents columns verified against the schema pages cited beside this query.
// MC1490905 says QR code detections carry "QRCode" in a UrlLocation column of MessageUrlInfo. The schema
// page read on 8 Oct 2026 does not list that column yet, so column_ifexists keeps the query valid
// before and after the rollout reaches the tenant.
MessageUrlInfo
| where Timestamp > ago(14d)
| extend UrlLocation = column_ifexists("UrlLocation", "")
| where isnotempty(ThreatTypes) or UrlLocation =~ "QRCode"
| join kind=leftouter (
    MessageEvents
    | where Timestamp > ago(14d)
    | project TeamsMessageId, SenderEmailAddress, IsExternalThread, ThreadSubtype, DeliveryAction
  ) on TeamsMessageId
| summarize Messages = dcount(TeamsMessageId),
            Senders = make_set(SenderEmailAddress, 20),
            FirstSeen = min(Timestamp), LastSeen = max(Timestamp)
          by UrlDomain, UrlLocation, ThreatTypes, IsExternalThread
| order by UrlLocation desc, Messages desc

// Microsoft SOC Brief 28 Sep 2026 - KB5129195/KB5129194 trust-relationship fallout
// Tables and columns verified against the DeviceEvents and DeviceInfo schema pages cited beside this query.
let win = ago(14d);
let patched =
    DeviceEvents
    | where Timestamp > win
    | where ActionType == "OsVersionChanged" or AdditionalFields has_any ("5129195", "5129194")
    | summarize PatchedAt = min(Timestamp) by DeviceId, DeviceName;
DeviceInfo
| where Timestamp > win
| where isnotempty(DeviceId)
| summarize arg_max(Timestamp, JoinType, OnboardingStatus, OSPlatform, OSVersion) by DeviceId, DeviceName
| where JoinType !in ("Hybrid Azure AD joined", "Azure AD joined")
| join kind=inner patched on DeviceId
| project DeviceName, DeviceId, OSPlatform, OSVersion, JoinType, PatchedAt, SeenAt = Timestamp
| order by PatchedAt asc

// Microsoft SOC Brief 28 Sep 2026 - workload-identity shape change
// Column names verified against the AADServicePrincipalSignInLogs table reference cited beside this query.
let lookback = 30d;
let recent = 2d;
let base =
    AADServicePrincipalSignInLogs
    | where TimeGenerated between (ago(lookback) .. ago(recent))
    | summarize BaseIPs = make_set(IPAddress, 200), BaseCalls = count() by ServicePrincipalId, ServicePrincipalName;
AADServicePrincipalSignInLogs
| where TimeGenerated > ago(recent)
| summarize NowCalls = count(), NowIPs = make_set(IPAddress, 200), Resources = make_set(ResourceDisplayName, 50)
          by ServicePrincipalId, ServicePrincipalName
| join kind=leftouter base on ServicePrincipalId
| extend NewIPs = set_difference(NowIPs, coalesce(BaseIPs, dynamic([])))
| extend DailyBase = todouble(coalesce(BaseCalls, 0)) / 28.0
| where array_length(NewIPs) > 0 or NowCalls > 5 * DailyBase
| project ServicePrincipalName, ServicePrincipalId, NowCalls, DailyBase = round(DailyBase, 1),
          NewIPs, Resources
| order by NowCalls desc
